    const card=root.querySelector('.form-card'),cfg=f.avatarConfig||{},editColor=colorForMbti(f.mbti,f.personalityColor);[...card.querySelectorAll('.field')].filter(field=>['性格色','头像图片地址'].includes(field.querySelector('label')?.textContent.trim())).forEach(field=>field.remove());card.querySelector('#editFriendBirthday').closest('.field').insertAdjacentHTML('afterend',`<div class="field"><label>其他重要日期</label><input id="editFriendImportantDates" class="input" value="${escapeHtml((f.importantDates||[]).map(x=>typeof x==='string'?x:(x.type||x.name||'')).filter(Boolean).join('、'))}"></div>`);card.querySelector('#editFriendMbti').closest('.field').insertAdjacentHTML('afterend',`<div class="field"><label>性格颜色</label><div class="mbti-color-result" id="editMbtiColorResult"><i style="background:${editColor}"></i>${personalityColorNames[editColor]} · 由 MBTI 自动生成</div></div>`);const gender=cfg.gender==='male'?'male':'female',styles=gender==='male'?[['male-01','温柔干净'],['male-02','阳光活力'],['male-03','简约成熟'],['male-04','随性自在']]:[['female-01','元气少女'],['female-02','温柔气质'],['female-03','清新简约'],['female-04','文艺治愈']];card.insertAdjacentHTML('beforeend',`<div class="field edit-avatar-field"><label>朋友形象</label><div class="edit-avatar-preview">${avatarMarkup(f,'avatar-option-image')}</div><div class="avatar-gender-row"><button type="button" class="${gender==='female'?'selected':''}" data-edit-avatar-gender="female">女生</button><button type="button" class="${gender==='male'?'selected':''}" data-edit-avatar-gender="male">男生</button></div><div class="fixed-avatar-options">${styles.map(([key,label])=>`<button type="button" class="fixed-avatar-card ${cfg.avatarStyle===key?'selected':''}" data-edit-avatar-style="${key}">${avatarMarkup({...cfg,personalityColor:editColor,avatarStyle:key},'avatar-option-image')}<span>${label}</span><i>✓</i></button>`).join('')}</div></div>`);
