  function renderProfile(){
    if(appMode==='user'&&state.userProfile.name==='你'&&!state.userProfile.mbti&&!state.userProfile.personalityTags.length)onboardingProfileDraft=normalizeProfile({...state.userProfile,name:''});
    const p=state.userProfile,screen=document.querySelector('[data-screen="profile"]');if(!screen)return;
    screen.querySelector('.profile-hero h1').textContent=p.name;screen.querySelector('.personal-signature').textContent=p.bio;screen.querySelector('.personal-trait-line').textContent=[p.mbti,...p.personalityTags].filter(Boolean).join(' · ');const ownAvatar=screen.querySelector('.self-person');if(ownAvatar){ownAvatar.innerHTML=avatarMarkup(p,'profile-own-avatar');ownAvatar.style.setProperty('--self-color',p.personalityColor)}screen.querySelector('.preference-row:first-of-type .preference-chips').innerHTML=p.personalityTags.map(x=>'<span>'+x+'</span>').join('');screen.querySelector('.preference-row:last-of-type .preference-chips').innerHTML=p.interests.map(x=>'<span>'+x+'</span>').join('');
    const edit=document.querySelector('[data-screen="profile-edit"]');if(!edit)return;
    profileEditDraft=normalizeProfile({...p,...profileEditDraft});edit.querySelector('#profileName').value=p.name;edit.querySelector('#profileMbti').innerHTML=`<option value="">暂不确定</option>${friendFormConfig.mbti.map(x=>`<option value="${x}" ${p.mbti===x?'selected':''}>${x}</option>`).join('')}`;edit.querySelector('#profileBio').value=p.bio;edit.querySelector('[data-edit-profile-avatar]').innerHTML=avatarMarkup(p,'profile-edit-avatar');edit.querySelector('[data-edit-profile-name]').textContent=p.name;edit.querySelector('[data-edit-profile-meta]').textContent=[p.mbti,...p.personalityTags].filter(Boolean).join(' · ');edit.querySelector('[data-edit-profile-bio]').textContent=p.bio;edit.querySelector('[data-profile-color-result]').innerHTML=`<i style="background:${p.personalityColor}"></i>${p.mbti?`${personalityColorNames[p.personalityColor]} · 由 MBTI 自动生成`:'暂未选择 · 使用中性色'}`;
    edit.querySelector('#profileAvatarEditor').innerHTML=profileAvatarPickerMarkup(profileEditDraft,'profile');edit.querySelector('#profilePersonalityEditor').innerHTML=friendFormConfig.personalityTags.map(x=>`<button type="button" class="chip ${p.personalityTags.includes(x)?'selected':''}" data-profile-trait="${x}">${x}</button>`).join('');edit.querySelectorAll('.profile-interest-details [data-profile-interest]').forEach(x=>x.classList.toggle('selected',p.interests.includes(x.textContent)));
    const preset=new Set([...edit.querySelectorAll('.profile-interest-details [data-profile-interest]')].map(x=>x.textContent.trim())),custom=edit.querySelector('.profile-interest-custom-list');custom.innerHTML=p.interests.filter(x=>!preset.has(x)).map(x=>`<button type="button" class="chip selected" data-profile-interest>${escapeHtml(x)}</button>`).join('');
    edit.querySelectorAll('[data-profile-interest-category]').forEach(x=>x.classList.remove('selected'));edit.querySelectorAll('[data-profile-interest-group]').forEach(x=>x.classList.remove('show'));const firstGroup=[...edit.querySelectorAll('[data-profile-interest-group]')].find(group=>[...group.querySelectorAll('[data-profile-interest]')].some(x=>x.classList.contains('selected')));if(firstGroup){firstGroup.classList.add('show');edit.querySelector(`[data-profile-interest-category="${firstGroup.dataset.profileInterestGroup}"]`)?.classList.add('selected')}
    renderOnboardingProfile();
  }
  function renderAll(){renderNav();renderHome();renderIsland();renderGiftLanding();renderInspirationFeed();renderInspirationDetail();renderPersonList();renderHouse();applyFriendHouseBackground();renderChoices();renderRecords();renderFriendForm();renderProfile();document.querySelectorAll('[data-current-mode-label]').forEach(x=>x.textContent=appMode==='user'?'我的 GiftLoop':'示例体验')}
  let firstFriendOnboarding=false;
  function setFirstFriendOnboarding(active){firstFriendOnboarding=active===true;const screen=document.querySelector('[data-screen="add-friend"]'),skip=document.querySelector('[data-skip-first-friend]'),title=document.querySelector('[data-add-friend-title]'),backButton=document.querySelector('[data-screen="add-friend"] [data-back]');screen?.classList.toggle('first-friend-onboarding',firstFriendOnboarding);if(skip){skip.hidden=!firstFriendOnboarding;skip.textContent=firstFriendOnboarding?'稍后再说':'跳过'}if(title)title.textContent=firstFriendOnboarding?'添加第一个朋友':'认识一位新朋友';if(backButton)backButton.hidden=firstFriendOnboarding}
  function openFirstFriendStep(){resetFriendForm();setFirstFriendOnboarding(true);show('add-friend',false)}
  function resolveStartScreen(){if(!appMode)return'mode-welcome';if(appMode==='demo')return'pick-friend';if(!state.onboarding.profileCompleted)return'onboard';if(!state.onboarding.firstFriendCompleted)return'add-friend';return'pick-friend'}
  function logStartupState(){}
  function routeFromAppState(){const destination=resolveStartScreen();logStartupState(destination);if(destination==='add-friend'){openFirstFriendStep();return}setFirstFriendOnboarding(false);show(destination,false)}
  function activateMode(mode){if(!['demo','user'].includes(mode))return;if(appMode==='user')persistCurrentData();appMode=mode;localStorage.setItem('giftloop_mode',mode);const source=getCurrentData(mode);state.friends=(source.friends||[]).map(normalizeFriend);state.notes=(source.memories||[]).map(note=>({...note,friendId:note.friendId||state.friends.find(f=>f.name===note.friend)?.id||''}));state.history=(source.giftRecords||[]).map(item=>({...item,friendId:item.friendId||state.friends.find(f=>f.name===item.friend)?.id||''}));state.onboarding=source.onboarding||emptyUserData().onboarding;state.userProfile=normalizeProfile(source.profile);onboardingProfileDraft=normalizeProfile({...state.userProfile,name:state.userProfile.name==='你'?'':state.userProfile.name});state.selected=null;state.stack=[];notePerson=state.friends[0]?.id||'';noteContextLocked=false;relationQuery='';relationFilter='all';recordFilter='全部';recordFriendScope='';setFirstFriendOnboarding(false);if(mode==='user')persistCurrentData();renderAll();hydrateMemoryPhotos();routeFromAppState()}
  function initApp(){renderFriendForm();renderRecs();renderAll();hydrateMemoryPhotos();routeFromAppState()}
