(function(){
  var preferenceScreen=document.querySelector('[data-screen="preferences"]');
  preferenceScreen.addEventListener('input',function(e){
    if(e.target.id==='giftBudgetMin')window.giftLoopUpdatePreferenceField('customBudgetMin',e.target.value);
    if(e.target.id==='giftBudgetMax')window.giftLoopUpdatePreferenceField('customBudgetMax',e.target.value);
    if(e.target.id==='giftOtherExclusionInput')window.giftLoopUpdatePreferenceField('giftExclusionNote',e.target.value);
    if(e.target.id==='giftContext')window.giftLoopUpdatePreferenceField('giftContext',e.target.value);
  });
  preferenceScreen.addEventListener('click',function(e){
    var occasion=e.target.closest('[data-occasion]');
    if(occasion){e.preventDefault();e.stopImmediatePropagation();window.giftLoopSetOccasion(occasion.dataset.occasion);return}
    var advancedToggle=e.target.closest('[data-toggle-gift-advanced]');
    if(advancedToggle){e.preventDefault();e.stopImmediatePropagation();window.giftLoopToggleAdvancedPreferences();return}
    if(e.target.closest('[data-edit-gift-friend]')){e.preventDefault();e.stopImmediatePropagation();window.giftLoopEditCurrentFriend();return}
    if(e.target.closest('[data-manage-gift-records]')){e.preventDefault();e.stopImmediatePropagation();window.giftLoopManageCurrentRecords();return}
    var generate=e.target.closest('[data-action="generate"]');
    if(generate){var validation=window.giftLoopValidateCustomBudget();e.preventDefault();e.stopImmediatePropagation();if(!validation.valid){window.giftLoopToast(validation.message);return}window.giftLoopGenerateGiftIdeas();return}
    var exclusionToggle=e.target.closest('[data-toggle-exclusions]');
    if(exclusionToggle){e.preventDefault();var exclusionRoot=document.getElementById('giftExclusionChips'),expanded=!exclusionRoot.classList.contains('expanded');exclusionRoot.classList.toggle('expanded',expanded);exclusionToggle.setAttribute('aria-expanded',String(expanded));exclusionToggle.textContent=expanded?'收起 ↑':'展开更多 ↓';return}
    var toggle=e.target.closest('[data-toggle-gift-preferences]');
    if(toggle){
      e.preventDefault();e.stopImmediatePropagation();
      var root=document.getElementById('feelingChips'),expanded=!root.classList.contains('expanded');
      root.classList.toggle('expanded',expanded);toggle.setAttribute('aria-expanded',String(expanded));toggle.textContent=expanded?'收起偏好 ↑':'更多偏好 ↓';return;
    }
    var giftForm=e.target.closest('[data-gift-form]');
    if(giftForm){
      var formValue=giftForm.dataset.giftForm;
      window.giftLoopTogglePreference('form',formValue);enhanceGiftFormControls();return;
    }
    var giftExclusion=e.target.closest('[data-gift-exclusion]');
    if(giftExclusion){
      var exclusionValue=giftExclusion.dataset.giftExclusion;
      window.giftLoopTogglePreference('exclusion',exclusionValue);
      return;
    }
    var feeling=e.target.closest('[data-feeling]');
    if(!feeling||feeling.classList.contains('selected'))return;
    var selected=document.querySelectorAll('#feelingChips [data-feeling].selected');
    if(selected.length>=2){e.preventDefault();e.stopPropagation();window.giftLoopToast('最多选择 2 个更在意的方向')}
  });
  function enhanceGiftFormControls(){document.querySelectorAll('#giftFormChips [data-gift-form]').forEach(function(button,index){var label=button.dataset.giftForm,selected=button.classList.contains('selected');button.className='gift-form-card '+(selected?'selected':'');button.innerHTML='<i class="gift-form-icon icon-'+(index%5)+'" aria-hidden="true"></i><span>'+label+'</span><b aria-hidden="true">✓</b>'})}
  enhanceGiftFormControls();
})();


document.addEventListener('click',event=>{
  const category=event.target.closest('[data-profile-interest-category]');
  if(category){
    const edit=category.closest('.profile-edit-screen'),wasSelected=category.classList.contains('selected');
    edit.querySelectorAll('[data-profile-interest-category]').forEach(item=>item.classList.remove('selected'));
    edit.querySelectorAll('[data-profile-interest-group]').forEach(group=>group.classList.remove('show'));
    if(!wasSelected){category.classList.add('selected');edit.querySelector(`[data-profile-interest-group="${category.dataset.profileInterestCategory}"]`)?.classList.add('show')}
    return;
  }
  if(event.target.closest('[data-open-profile-interest]')){
    const box=document.querySelector('.profile-custom-interest');box.hidden=!box.hidden;
    if(!box.hidden)setTimeout(()=>document.getElementById('customProfileInterest')?.focus(),0);
    return;
  }
  if(event.target.closest('[data-add-profile-interest]')){
    const input=document.getElementById('customProfileInterest'),value=input?.value.trim();
    if(value){
      const exists=[...document.querySelectorAll('[data-profile-interest]')].some(item=>item.textContent.trim()===value);
      if(!exists)document.querySelector('.profile-interest-custom-list').insertAdjacentHTML('beforeend',`<button type="button" class="chip selected" data-profile-interest>${escapeHtml(value)}</button>`);
      input.value='';
    }
  }
});


(() => {
  let activeMemoryIndex=-1;
  let editingNoteIndex=-1;
  document.addEventListener('error',event=>{const image=event.target;if(!(image instanceof HTMLImageElement)||!image.matches('[data-gift-image-fallback]')||image.dataset.fallbackApplied)return;image.dataset.fallbackApplied='true';image.src=image.dataset.giftImageFallback},true);
  const actions=()=>document.getElementById('memoryActions');
  const closeActions=()=>{const el=actions();if(!el)return;el.classList.remove('show');el.setAttribute('aria-hidden','true')};
  const openActions=index=>{activeMemoryIndex=index;const el=actions();if(!el)return;el.classList.add('show');el.setAttribute('aria-hidden','false')};
  const dateInputValue=value=>{const match=String(value||'').match(/(\d{1,2})月(\d{1,2})日/);return match?`2026-${String(match[1]).padStart(2,'0')}-${String(match[2]).padStart(2,'0')}`:''};

  document.addEventListener('click',async event=>{
    if(event.target.closest('[data-close-note]')){editingNoteIndex=-1;delete document.getElementById('recordComposer')?.dataset.editingFriendId}
    const adjustment=event.target.closest('[data-adjust]');
    if(adjustment){event.preventDefault();event.stopImmediatePropagation();window.giftLoopAdjustResults?.(adjustment.dataset.adjust);return}
    if(event.target.closest('[data-retry-gift],[data-regenerate-gift],[data-action="regenerate"]')){event.preventDefault();event.stopImmediatePropagation();if(event.target.closest('[data-retry-gift]'))window.giftLoopResultActions?.retry();else window.giftLoopResultActions?.regenerate();return}
    if(event.target.closest('[data-previous-results]')){event.preventDefault();event.stopImmediatePropagation();window.giftLoopResultActions?.restore();return}
    if(event.target.closest('[data-cancel-gift]')){event.preventDefault();event.stopImmediatePropagation();window.giftLoopCancelGift?.();return}
    if(event.target.closest('[data-return-preferences]')){event.preventDefault();event.stopImmediatePropagation();window.giftLoopReturnPreferences?.();return}
    const newNoteSave=editingNoteIndex<0&&event.target.closest('[data-save-note]');
    if(newNoteSave){
      event.preventDefault();event.stopImmediatePropagation();
      await window.giftLoopSaveNote?.();return;
    }
    const detailToggle=event.target.closest('[data-recommend-detail]');
    if(detailToggle){
      event.preventDefault();event.stopImmediatePropagation();
      const panel=detailToggle.nextElementSibling,expanded=detailToggle.getAttribute('aria-expanded')==='true';
      detailToggle.setAttribute('aria-expanded',String(!expanded));
      detailToggle.firstChild.nodeValue=expanded?'为什么推荐？':'收起理由 ';
      if(panel)panel.hidden=expanded;
      return;
    }
    const saveIdea=event.target.closest('[data-save-idea]');
    if(saveIdea){event.preventDefault();event.stopImmediatePropagation();const active=window.giftLoopResultActions?.toggleSaved(saveIdea.dataset.saveIdea);if(active!==null)window.giftLoopToast(active?'已经收藏这个灵感':'已取消收藏');return}
    if(event.target.closest('[data-save-direction-detail]')){event.preventDefault();event.stopImmediatePropagation();const active=window.giftLoopResultActions?.toggleDetailSaved();if(active!==null)window.giftLoopToast(active?'已经收藏这个灵感':'已取消收藏');return}
    const openDirection=event.target.closest('[data-open-gift-direction]');
    if(openDirection){event.preventDefault();event.stopImmediatePropagation();window.giftLoopResultActions?.open(openDirection.dataset.openGiftDirection);return}
    const selectProduct=event.target.closest('[data-select-product]');
    if(selectProduct){event.preventDefault();event.stopImmediatePropagation();window.giftLoopResultActions?.selectProduct(selectProduct.dataset.selectProduct);return}
    if(event.target.closest('[data-select-gift-direction]')){event.preventDefault();event.stopImmediatePropagation();window.giftLoopResultActions?.beginRecord();return}
    const editHouseDates=event.target.closest('[data-edit-house-dates]');
    if(editHouseDates){event.preventDefault();event.stopImmediatePropagation();renderFriendEdit();show('friend-edit');setTimeout(()=>document.getElementById('editFriendBirthday')?.scrollIntoView({block:'center'}),0);return}
    const allHouseMemories=event.target.closest('[data-house-all-memories]');
    if(allHouseMemories){event.preventDefault();event.stopImmediatePropagation();recordFriendScope=allHouseMemories.dataset.houseAllMemories;recordFilter='日常';renderRecords();show('records');return}
    const houseMemory=event.target.closest('[data-house-memory]');
    if(houseMemory){event.preventDefault();event.stopImmediatePropagation();const id=houseMemory.dataset.houseMemory,friendId=houseMemory.dataset.houseMemoryFriend;recordFriendScope=friendId;recordFilter='日常';renderRecords();show('records');setTimeout(()=>{const index=renderedMemories.findIndex(memory=>(memory.id&&memory.id===id)||String(memory._sourceIndex)===id);document.querySelector(`[data-memory-index="${index}"]`)?.click()},0);return}
    const allHouseGifts=event.target.closest('[data-house-all-gifts]');
    if(allHouseGifts){event.preventDefault();event.stopImmediatePropagation();recordFriendScope=allHouseGifts.dataset.houseAllGifts;recordFilter='礼物';renderRecords();show('records');return}
    const regularRecords=event.target.closest('[data-go="records"]');if(regularRecords&&!event.target.closest('[data-screen="friend-house"]'))recordFriendScope='';
    const houseGift=event.target.closest('[data-screen="friend-house"] [data-start-for]');
    if(houseGift){event.preventDefault();event.stopImmediatePropagation();window.giftLoopOpenFlow(houseGift.dataset.startFor);return}
    const houseNote=event.target.closest('[data-house-note]');
    if(houseNote){
      event.preventDefault();event.stopImmediatePropagation();
      window.giftLoopOpenNote(houseNote.dataset.houseNote);
      return;
    }
    const menu=event.target.closest('[data-memory-menu]');
    if(menu){event.preventDefault();event.stopImmediatePropagation();openActions(Number(menu.dataset.memoryMenu));return}
    if(event.target.closest('[data-close-memory-actions]')){event.preventDefault();event.stopImmediatePropagation();closeActions();return}
    const action=event.target.closest('[data-memory-action]');
    if(action){
      event.preventDefault();event.stopImmediatePropagation();
      const memory=window.giftLoopMemoryActions?.get(activeMemoryIndex);
      if(!memory){closeActions();return}
      if(action.dataset.memoryAction==='gift'){
        closeActions();
        window.giftLoopMemoryActions?.startGift(memory);
        window.giftLoopToast('已把这条记忆带进送礼灵感');
        return;
      }
      if(action.dataset.memoryAction==='delete'){
        if(confirm('确定删除这条记录吗？')){
          await window.giftLoopMemoryActions?.remove(memory);
          closeActions();window.giftLoopToast('这条记录已删除');
        }
        return;
      }
      if(action.dataset.memoryAction==='edit'){
        if(memory._source!=='note'){closeActions();window.giftLoopToast('礼物记录请在朋友小屋中管理');return}
        editingNoteIndex=memory._sourceIndex;
        const editingFriendId=memory.friendId||'';
        document.getElementById('noteEvent').value=memory.event||'';
        document.getElementById('noteExtra').value=memory.detail||'';
        document.getElementById('noteTag').value=(memory.tags||[])[0]||'';
        document.getElementById('noteDate').value=dateInputValue(memory.date);
        closeActions();
        document.getElementById('recordComposer').classList.add('show');
        document.getElementById('recordComposer').setAttribute('aria-hidden','false');
        document.getElementById('recordComposer').dataset.editingFriendId=editingFriendId;
        return;
      }
    }
    if(editingNoteIndex>=0&&event.target.closest('[data-save-note]')){
      event.preventDefault();event.stopImmediatePropagation();
      const title=document.getElementById('noteEvent').value.trim();
      if(!title){window.giftLoopToast('先记下发生了什么');return}
      const composer=document.getElementById('recordComposer');
      window.giftLoopMemoryActions?.update(editingNoteIndex,{friendId:composer.dataset.editingFriendId,event:title,detail:document.getElementById('noteExtra').value.trim(),rawDate:document.getElementById('noteDate').value,tag:document.getElementById('noteTag').value.trim()});
      editingNoteIndex=-1;
      delete composer.dataset.editingFriendId;
      composer.classList.remove('show');
      composer.setAttribute('aria-hidden','true');
      window.giftLoopToast('记录已更新');return;
    }
    if(event.target.closest('[data-start-gift-flow],[data-start-gift]'))window.giftloopMemoryContext=null;
  },true);
})();
